// === Tab: Sketch ===
let theShader;
let timeOff;

function setup() {
	theShader = createShader(vert, frag);
  createCanvas(600, 600, WEBGL);
	timeOff = random(100);
  noStroke();
}

function draw() {
  shader(theShader);
  theShader.setUniform('u_resolution', [windowWidth/1000, windowHeight/1000]);
  theShader.setUniform('u_time', millis()/1000 + timeOff);
  theShader.setUniform('uScale', 0.5);
  rect(0, 0, width, height);
}

 const vert = `
    attribute vec3 aPosition;
    attribute vec2 aTexCoord;
    varying vec2 vTexCoord;
    void main() {
      vTexCoord = aTexCoord;
      vec4 positionVec4 = vec4(aPosition, 1.0);
      positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
      gl_Position = positionVec4;
    }
  `;

  const frag = `
    #ifdef GL_ES
    precision mediump float;
    #endif

    varying vec2 vTexCoord;
    uniform vec2 u_resolution;
    uniform float u_time;
    uniform float uScale;

    // Simplex 3D Noise 
    // by Ian McEwan, Ashima Arts

    vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
    vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}

    float snoise(vec3 v){ 
      const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
      const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);

      vec3 i  = floor(v + dot(v, C.yyy) );
      vec3 x0 =   v - i + dot(i, C.xxx) ;

      vec3 g = step(x0.yzx, x0.xyz);
      vec3 l = 1.0 - g;
      vec3 i1 = min( g.xyz, l.zxy );
      vec3 i2 = max( g.xyz, l.zxy );

      //  x0 = x0 - 0. + 0.0 * C 
      vec3 x1 = x0 - i1 + 1.0 * C.xxx;
      vec3 x2 = x0 - i2 + 2.0 * C.xxx;
      vec3 x3 = x0 - 1. + 3.0 * C.xxx;

      i = mod(i, 289.0 ); 
      vec4 p = permute( permute( permute( 
                 i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
               + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) 
               + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));

      float n_ = 1.0/7.0; // N=7
      vec3  ns = n_ * D.wyz - D.xzx;

      vec4 j = p - 49.0 * floor(p * ns.z *ns.z);  //  mod(p,N*N)

      vec4 x_ = floor(j * ns.z);
      vec4 y_ = floor(j - 7.0 * x_ );    // mod(j,N)

      vec4 x = x_ *ns.x + ns.yyyy;
      vec4 y = y_ *ns.x + ns.yyyy;
      vec4 h = 1.0 - abs(x) - abs(y);

      vec4 b0 = vec4( x.xy, y.xy );
      vec4 b1 = vec4( x.zw, y.zw );

      vec4 s0 = floor(b0)*2.0 + 1.0;
      vec4 s1 = floor(b1)*2.0 + 1.0;
      vec4 sh = -step(h, vec4(0.0));

      vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
      vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;

      vec3 p0 = vec3(a0.xy,h.x);
      vec3 p1 = vec3(a0.zw,h.y);
      vec3 p2 = vec3(a1.xy,h.z);
      vec3 p3 = vec3(a1.zw,h.w);

      vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
      p0 *= norm.x;
      p1 *= norm.y;
      p2 *= norm.z;
      p3 *= norm.w;

      vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
      m = m * m;
      return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), 
                    dot(p2,x2), dot(p3,x3) ) );
    }

    float Bayer2(vec2 a) {
      a = floor(a);
      return fract(a.x / 2.0 + a.y * a.y * 0.75);
    }

    #define Bayer4(a)   (Bayer2(0.5*(a)) * 0.25 + Bayer2(a))
    #define Bayer8(a)   (Bayer4(0.5*(a)) * 0.25 + Bayer2(a))
    #define Bayer16(a)  (Bayer8(0.5*(a)) * 0.25 + Bayer2(a))
    #define Bayer32(a)  (Bayer16(0.5*(a)) * 0.25 + Bayer2(a))
    #define Bayer64(a)  (Bayer32(0.5*(a)) * 0.25 + Bayer2(a))

    void main() {
      vec2 st = vTexCoord.xy/u_resolution.xy;
      st.x *= u_resolution.x/u_resolution.y;

      float time_factor = 0.12;

      float noize = snoise(vec3(st.x - u_time*time_factor, st.y, u_time*0.02)*1.5);

      float color_noize = snoise(vec3(st.x + u_time*time_factor, st.y, 10. + u_time*0.02)*1.5);
      float alpha = 10.0;
      float off = 0.5;
      float fact = 0.5;

      float gray;
      if (mod(floor(noize*10.),2.) == 0.) {
        float trig1 = cos(color_noize*alpha*1.0);
        float trig2 = cos(color_noize*alpha*1.2);
        float trig3 = cos(color_noize*alpha*1.4);
        gray = off + fact * (0.299*trig1 + 0.587*trig2 + 0.114*trig3);
      } else {
        float trig1 = sin(color_noize*alpha*1.0);
        float trig2 = sin(color_noize*alpha*1.2);
        float trig3 = sin(color_noize*alpha*1.4);
        gray = off + fact * (0.299*trig1 + 0.587*trig2 + 0.114*trig3);
      }

      vec2 fragCoord = gl_FragCoord.xy;
      float m = Bayer32(fragCoord * uScale);
      float d = step(m, gray);

      gl_FragColor = vec4(vec3(d), 1.0);
    }
  `;

